from pyquest import *


def draw_bird(x, y):
    draw_image("images/bird.png", x, y)


def draw_pipe(x, gap_y):
    draw_image("images/pipe.png", x, gap_y - 440, flip=True)
    draw_image("images/pipe.png", x, gap_y + GAP)


GAP = 150
y = 300
speed = 0
pipe_x = 400
pipe_gap = 150
game_over = False


def hits():
    if 100 + 44 - 8 < pipe_x or 100 + 8 > pipe_x + 52:
        return False
    return y + 8 < pipe_gap or y + 40 - 8 > pipe_gap + GAP


def update():
    global y, speed, pipe_x, game_over
    if game_over:
        return
    if key_pressed():
        speed = -8
    speed = speed + 0.5
    y = y + speed
    if y > 480:
        y = 480
        speed = 0
    pipe_x = pipe_x - 2
    if hits():
        game_over = True


def draw():
    clear("skyblue")
    draw_pipe(pipe_x - 12, pipe_gap)
    draw_bird(100, y)
    if game_over:
        draw_text("Thua rồi!", 200, 250, 48)
